//! Objective-C Runtime bindings for functions and typings that involve method selectors.

const std = @import("std");

/// @brief Defines an opaque type that represents a method selector.
///
/// @details Method selectors are used to represent the name of a method at runtime. A method
///          selector is a C string that has been registered (or “mapped”) with the Objective-C
///          runtime. Selectors generated by the compiler are automatically mapped by the runtime
///          when the class is loaded.
///
///          You can add new selectors at runtime and retrieve existing selectors using the
///          function `selRegisterName(_:)`.
///
///          When using selectors, you must use the value returned from `selRegisterName(_:)` or
///          the Objective-C compiler directive `@selector()`. You cannot simply cast a C string to
///          `Sel`.
///
/// @remarks The original name for this type in the Objective-C runtime is `SEL`.
///
/// @see [Objective-C Runtime Docs](https://developer.apple.com/documentation/objectivec/sel)
pub const Sel = opaque {};

/// @brief Returns the name of the method specified by a given selector.
///
/// @param sel A pointer of type `Sel`. Pass the selector whose name you wish to determine
/// @returns A C string indicating the name of the selector
///
/// @remarks The original name for this function in the Objective-C runtime is `sel_getName`.
///
/// @see [Objective-C Runtime Docs](https://developer.apple.com/documentation/objectivec/sel_getname(_:))
pub fn selGetName(sel: *Sel) []const u8 {
    return std.mem.span(sel_getName(sel));
}

/// @brief Registers a method name with the Objective-C runtime system.
///
/// @param str A pointer to a C string. Pass the name of the method you wish to register
/// @returns A pointer of type `Sel` specifying the selector for the named method
///
/// @details The implementation of this method is identical to the implementation of
///          `selRegisterName`.
///
/// @note Prior to OS X version 10.0, this method tried to find the selector mapped to the given
///       name and returned `null` if the selector was not found. This was changed for safety,
///       because it was observed that many of the callers of this function did not check the
///       return value for `null`.
///
/// @remarks The original name for this function in the Objective-C runtime is `sel_getUid`.
///
/// @see [Objective-C Runtime Docs](https://developer.apple.com/documentation/objectivec/sel_getuid(_:))
pub fn selGetUid(str: [*:0]const u8) *Sel {
    return sel_getUid(str);
}

/// @brief Returns a Boolean value that indicates whether two selectors are equal.
///
/// @param lhs The selector to compare with `rhs`
/// @param rhs The selector to compare with `lhs`
/// @returns `true` if `lhs` and `rhs` are equal, otherwise `false`
///
/// @details `sel_isEqual` is equivalent to `==`.
///
/// @remarks The original name for this function in the Objective-C runtime is `sel_isEqual`.
///
/// @see [Objective-C Runtime Docs](https://developer.apple.com/documentation/objectivec/sel_isequal(_:_:))
pub fn selIsEqual(lhs: *Sel, rhs: *Sel) bool {
    return sel_isEqual(lhs, rhs);
}

/// @brief Registers a method with the Objective-C runtime system, maps the method name to a
///        selector, and returns the selector value.
///
/// @param str A pointer to a C string. Pass the name of the method you wish to register
/// @returns A pointer of type `Sel` specifying the selector for the named method
///
/// @details You must register a method name with the Objective-C runtime system to obtain the
///          method’s selector before you can add the method to a class definition. If the method
///          name has already been registered, this function simply returns the selector.
///
/// @remarks The original name for this function in the Objective-C runtime is `sel_registerName`.
///
/// @see [Objective-C Runtime Docs](https://developer.apple.com/documentation/objectivec/sel_registername(_:))
pub fn selRegisterName(str: [*:0]const u8) *Sel {
    return sel_registerName(str);
}

extern "objc" fn sel_getName(sel: *Sel) callconv(.c) [*:0]const u8;
extern "objc" fn sel_getUid(str: [*:0]const u8) callconv(.c) *Sel;
extern "objc" fn sel_isEqual(lhs: *Sel, rhs: *Sel) callconv(.c) bool;
extern "objc" fn sel_registerName(str: [*:0]const u8) callconv(.c) *Sel;

test selGetName {
    // It should return the provided method selector's name as a u8 slice
    const sel = selRegisterName("alloc");
    try std.testing.expect(std.mem.eql(u8, selGetName(sel), "alloc"));
}

test selGetUid {
    // It should register a method selector with the provided name
    const sel = selGetUid("alloc");
    try std.testing.expect(std.mem.eql(u8, selGetName(sel), "alloc"));
}

test selIsEqual {
    // It should return true of the two provided method selectors are equal.
    const sel1 = selRegisterName("alloc");
    const sel2 = selRegisterName("alloc");
    const sel3 = selRegisterName("init");

    try std.testing.expect(selIsEqual(sel1, sel2));
    try std.testing.expect(selIsEqual(sel1, sel3) == false);
    try std.testing.expect(selIsEqual(sel2, sel3) == false);
}

test selRegisterName {
    // It should register a method selector with the provided name
    const sel = selRegisterName("alloc");
    try std.testing.expect(std.mem.eql(u8, selGetName(sel), "alloc"));
}
